// Generate TypeScript types from the contracts the backend validates against (schemas/*.json).
// `--check` fails when a generated file is stale, so the UI can never drift from the API.
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";
import openapiTS, { astToString } from "openapi-typescript";

const here = path.dirname(fileURLToPath(import.meta.url));
const schemas = path.resolve(here, "../../schemas");
const out = path.resolve(here, "../src/types/generated");
const check = process.argv.includes("--check");
const banner = "// GENERATED by web/scripts/gen-types.mjs from schemas/. Do not edit by hand.\n";

const jsonSchemas = {
  "statement-pack.ts": "statement_pack.schema.json",
  "ratio-pack.ts": "ratio_pack.schema.json",
  "commentary.ts": "commentary.schema.json",
};

async function build() {
  const files = {};
  for (const [target, source] of Object.entries(jsonSchemas)) {
    const schema = JSON.parse(await readFile(path.join(schemas, source), "utf8"));
    files[target] = await compile(schema, schema.title ?? source, {
      bannerComment: banner,
      additionalProperties: false,
      cwd: schemas,
      style: { printWidth: 100 },
    });
  }
  const api = JSON.parse(await readFile(path.join(schemas, "openapi.json"), "utf8"));
  files["api.ts"] = banner + astToString(await openapiTS(api));
  return files;
}

const files = await build();
let stale = [];
for (const [name, text] of Object.entries(files)) {
  const target = path.join(out, name);
  if (check) {
    const current = await readFile(target, "utf8").catch(() => "");
    if (current !== text) stale.push(name);
  } else {
    await writeFile(target, text);
  }
}
if (stale.length) {
  console.error(`stale generated types: ${stale.join(", ")} (run: npm run types)`);
  process.exit(1);
}
console.log(check ? "generated types are current" : `wrote ${Object.keys(files).length} files`);
